export const refunds = pgTable("refunds", {
  id: serial("id").primaryKey(),
  transactionId: integer("transaction_id").references(() => transactions.id),
  merchantId: integer("merchant_id").references(() => merchants.id),
  refundAmount: decimal("refund_amount", { precision: 10, scale: 2 }).notNull(),
  refundReason: text("refund_reason"),
  refundMethod: text("refund_method").default("original_payment_method"), // original_payment_method, bank_transfer, manual
  status: text("status").notNull().default("pending"), // pending, processing, completed, failed
  windcaveRefundId: text("windcave_refund_id"), // External refund processor ID

  // Fee handling for refunds
  windcaveFeeRefunded: decimal("windcave_fee_refunded", { precision: 10, scale: 2 }).default("0.00"),
  platformFeeRefunded: decimal("platform_fee_refunded", { precision: 10, scale: 2 }).default("0.00"),

  initiatedBy: text("initiated_by"), // merchant, customer, admin
  customerNotified: boolean("customer_notified").default(false),
  completedAt: timestamp("completed_at"),
  createdAt: timestamp("created_at").defaultNow(),
});

// Platform settlements - tracks money owed to merchants (Marketplace Model)
export const merchantSettlements = pgTable("merchant_settlements", {
  id: serial("id").primaryKey(),
  merchantId: integer("merchant_id").references(() => merchants.id),
  settlementPeriod: text("settlement_period").notNull(), // e.g., "2025-01-01"
  totalTransactionAmount: decimal("total_transaction_amount", { precision: 10, scale: 2 }).notNull(),
  totalWindcaveFees: decimal("total_windcave_fees", { precision: 10, scale: 2 }).notNull(),
  totalPlatformFees: decimal("total_platform_fees", { precision: 10, scale: 2 }).notNull(),
  netSettlementAmount: decimal("net_settlement_amount", { precision: 10, scale: 2 }).notNull(),
  status: text("status").notNull().default("pending"), // pending, processing, completed, failed
  settlementDate: timestamp("settlement_date"),
  createdAt: timestamp("created_at").defaultNow(),
});

// Platform fees table for tracking revenue collection
export const platformFees = pgTable("platform_fees", {
  id: serial("id").primaryKey(),
  transactionId: integer("transaction_id").references(() => transactions.id),
  merchantId: integer("merchant_id").references(() => merchants.id),
  feeAmount: decimal("fee_amount", { precision: 10, scale: 2 }).notNull(),
  transactionAmount: decimal("transaction_amount", { precision: 10, scale: 2 }).notNull(),
  status: text("status").notNull().default("pending"), // pending, collected, failed
  collectedAt: timestamp("collected_at"),
  createdAt: timestamp("created_at").defaultNow(),
});

// Split payments schemas
export const insertSplitPaymentSchema = createInsertSchema(splitPayments).omit({
  id: true,
  createdAt: true,
  paidAt: true,
});

export const createSplitPaymentSchema = z.object({
  transactionId: z.number().min(1, "Transaction ID is required"),
  splitIndex: z.number().min(1, "Split index is required"),
  amount: z.string().refine((val) => {
    const num = parseFloat(val);
    return !isNaN(num) && num > 0;
  }, "Amount must be a positive number"),

export const invoicesRentRequests = pgTable("invoices_rent_requests", {
  id: uuid("id").primaryKey().defaultRandom(),
  merchantId: integer("merchant_id").references(() => merchants.id).notNull(),
  tenantProfileId: uuid("tenant_profile_id").references(() => tenantProfiles.id).notNull(),
  scheduleId: uuid("schedule_id").references(() => activeSchedules.id),
  amountCents: integer("amount_cents").notNull(),
  token: text("token").notNull().unique(),
  deliveryChannel: text("delivery_channel").notNull(),
  billingPeriodStart: timestamp("billing_period_start"),
  // What this invoice is for. "rent" is the default (recurring or one-off rent);
  // "charge" is a one-off non-rent bill (utilities, late fee, cleaning, damages, other).
  // chargeType carries the category, description the human-readable label shown to the tenant.
  kind: text("kind").notNull().default("rent"),
  chargeType: text("charge_type"),
  description: text("description"),
  // Optional supporting document (PDF/image) attached to a one-off charge. Shown
  // to the tenant on the checkout page as a "View invoice" link they can open,
  // download or share. Null for rent and for charges sent without an attachment.
  documentUrl: text("document_url"),
  documentName: text("document_name"),
  status: text("status").notNull().default("pending_dispatch"),
  dueAt: timestamp("due_at").notNull(),
  dispatchedAt: timestamp("dispatched_at"),
  sentAt: timestamp("sent_at"),
  paidAt: timestamp("paid_at"),
  voidedAt: timestamp("voided_at"),
  externalPaymentReference: text("external_payment_reference"),
  lastReminderSentAt: timestamp("last_reminder_sent_at"),
  reminderCount: integer("reminder_count").notNull().default(0),
  windcaveSessionId: text("windcave_session_id"),
  windcaveTransactionId: text("windcave_transaction_id"),
  // Split-bill: the merchant enables it; the tenant chooses how many flatmates
  // share the rent on the checkout page. Each share is paid via the same link.
  splitEnabled: boolean("split_enabled").notNull().default(false),
  splitCount: integer("split_count"),                       // chosen number of ways (null until tenant splits)
  splitPaidCount: integer("split_paid_count").notNull().default(0),
  splitPaidSessions: text("split_paid_sessions").array(),   // Windcave session ids already counted (idempotency)
  splitPayerEmails: text("split_payer_emails").array(),     // emails collected from share payers (for GST copies)
  // WhatsApp delivery tracking: Evolution API message ID stored at send time;
  // whatsappDeliveredAt set when the DELIVERY_ACK webhook arrives.
  whatsappMessageId: text("whatsapp_message_id"),
  whatsappDeliveredAt: timestamp("whatsapp_delivered_at"),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
}, (t) => ({
  scheduleBillingPeriodUnique: uniqueIndex("invoices_schedule_billing_period_unique")
    .on(t.scheduleId, t.billingPeriodStart)
    .where(sql`${t.scheduleId} IS NOT NULL AND ${t.billingPeriodStart} IS NOT NULL`),
  statusDueIdx: index("invoices_status_due_idx").on(t.status, t.dueAt),
  merchantStatusIdx: index("invoices_merchant_status_idx").on(t.merchantId, t.status),
  tokenIdx: index("invoices_token_idx").on(t.token),
  whatsappMsgIdx: index("invoices_whatsapp_message_idx").on(t.whatsappMessageId),
}));

export const transactionEvents = pgTable("transaction_events", {
  id: uuid("id").primaryKey().defaultRandom(),
  merchantId: integer("merchant_id").references(() => merchants.id).notNull(),
  tenantProfileId: uuid("tenant_profile_id").references(() => tenantProfiles.id),
  invoiceId: uuid("invoice_id").references(() => invoicesRentRequests.id),
  scheduleId: uuid("schedule_id").references(() => activeSchedules.id),
  eventType: text("event_type").notNull(),
  payload: jsonb("payload"),
  createdAt: timestamp("created_at").defaultNow(),
}, (t) => ({
  tenantCreatedIdx: index("transaction_events_tenant_created_idx").on(t.tenantProfileId, t.createdAt),
  merchantCreatedIdx: index("transaction_events_merchant_created_idx").on(t.merchantId, t.createdAt),
}));

// Property management Zod schemas
const propertyAddressSchema = z.string().trim().min(1, "Property address is required").max(200);
const personNameSchema = z.string().trim().min(1).max(80);
const optionalEmailSchema = z.string().trim().email().max(200).optional().or(z.literal("")).transform(v => v || undefined);
const optionalPhoneSchema = z.string().trim().min(1).max(40).optional().or(z.literal("")).transform(v => v || undefined);

const tenantProfileFields = z.object({
  firstName: personNameSchema,
  lastName: personNameSchema,
  email: optionalEmailSchema,
  phone: optionalPhoneSchema,
  propertyAddress: propertyAddressSchema,
  coTenantsText: z.string().max(1000).optional().or(z.literal("")).transform(v => v || undefined),
  preferredChannel: z.enum(["email", "whatsapp", "sms"]).default("email"),
});

export const createTenantProfileSchema = tenantProfileFields;
export const updateTenantProfileSchema = tenantProfileFields.partial();

export const createActiveScheduleSchema = z.object({
  tenantProfileId: z.string().uuid(),
  amountCents: z.number().int().positive().max(100_000_000),
  frequency: z.enum(["weekly", "fortnightly", "monthly"]),
  deliveryChannel: z.enum(["email", "whatsapp", "sms"]),
  startDate: z.string().datetime().or(z.date()).transform(v => new Date(v as any)),
  endDate: z.string().datetime().or(z.date()).optional().transform(v => v ? new Date(v as any) : undefined),
});

// Pause/resume is driven by `status` (active ↔ paused); the legacy pauseNextCycle
// flag is no longer accepted from clients.
export const updateActiveScheduleSchema = z.object({
  amountCents: z.number().int().positive().max(100_000_000).optional(),
  frequency: z.enum(["weekly", "fortnightly", "monthly"]).optional(),
  deliveryChannel: z.enum(["email", "whatsapp", "sms"]).optional(),
  status: z.enum(["active", "paused", "terminated"]).optional(),
});

export const updateRentReminderSettingsSchema = z.object({
  rentReminderEnabled: z.boolean().optional(),
  rentReminderDelayDays: z.number().int().min(0).max(90).optional(),
  rentReminderIntervalDays: z.number().int().min(1).max(90).optional(),
  rentReminderMaxCount: z.number().int().min(0).max(20).optional(),
});

export const createAdHocInvoiceSchema = z.object({
  tenantProfileId: z.string().uuid(),
  amountCents: z.number().int().positive().max(100_000_000),
  deliveryChannel: z.enum(["email", "whatsapp", "sms"]),
  dueAt: z.string().datetime().or(z.date()).transform(v => new Date(v as any)),
  splitEnabled: z.boolean().optional(),
  // One-off non-rent charges carry kind="charge" plus a category and label.
  // Rent (the default) omits these.
  kind: z.enum(["rent", "charge"]).optional(),
  chargeType: z.enum(["utilities", "late_fee", "cleaning", "damages", "other"]).optional(),
  description: z.string().trim().max(200).optional().or(z.literal("")).transform(v => v || undefined),
  // Optional attached invoice document (a URL returned by the upload endpoint).
  documentUrl: z.string().trim().max(500).optional().or(z.literal("")).transform(v => v || undefined),
  documentName: z.string().trim().max(255).optional().or(z.literal("")).transform(v => v || undefined),
});

export const markInvoicePaidExternalSchema = z.object({
  externalPaymentReference: z.string().trim().max(200).optional().or(z.literal("")).transform(v => v || undefined),
});

// Property management types
export type TenantProfile = typeof tenantProfiles.$inferSelect;
export type InsertTenantProfile = typeof tenantProfiles.$inferInsert;
export type ActiveSchedule = typeof activeSchedules.$inferSelect;
export type InsertActiveSchedule = typeof activeSchedules.$inferInsert;
export type InvoiceRentRequest = typeof invoicesRentRequests.$inferSelect;
export type InsertInvoiceRentRequest = typeof invoicesRentRequests.$inferInsert;
export type TransactionEvent = typeof transactionEvents.$inferSelect;

