1	/**
2	 * gst-invoice.ts — emails a NZ GST tax invoice/receipt to every payer after a
3	 * rent payment settles (head tenant + any co-tenants + split-share payers).
4	 *
5	 * GST is computed as 15% inclusive of the amount paid (NZ standard rate):
6	 *   gst = round(total * 3 / 23),  net = total - gst.
7	 */
8	
9	import { sendEmail } from "./email-service";
10	
11	function fmtCents(c: number): string { return `$${(c / 100).toFixed(2)}`; }
12	function fmtDate(d: Date): string {
13	  return new Date(d).toLocaleDateString("en-NZ", { day: "numeric", month: "long", year: "numeric" });
14	}
15	
16	const EMAIL_RE = /[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi;
17	
18	/** Pull any email addresses out of free text (e.g. the co-tenants field). */
19	export function extractEmails(text?: string | null): string[] {
20	  if (!text) return [];
21	  return (text.match(EMAIL_RE) || []).map((e) => e.toLowerCase());
22	}
23	
24	function buildGstInvoiceEmail(opts: {
25	  merchantName: string; gstNumber?: string | null;
26	  tenantName: string; propertyAddress: string;
27	  amountCents: number; netCents: number; gstCents: number;
28	  paidAt: Date; reference: string;
29	}): { subject: string; html: string; text: string } {
30	  const { merchantName, gstNumber, tenantName, propertyAddress, amountCents, netCents, gstCents, paidAt, reference } = opts;
31	  const total = fmtCents(amountCents);
32	  const net   = fmtCents(netCents);
33	  const gst   = fmtCents(gstCents);
34	  const paid  = fmtDate(paidAt);
35	  const subject = `Tax invoice — rent payment ${total} · ${reference}`;
36	
37	  const gstLine = gstNumber
38	    ? `<p style="margin:0;font-size:12px;color:#8C8C8C">GST no. ${gstNumber}</p>`
39	    : "";
40	
41	  const html = `<!DOCTYPE html>
42	<html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head>
43	<body style="margin:0;padding:0;background:#F4F4F4;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif">
44	  <table width="100%" cellpadding="0" cellspacing="0" style="background:#F4F4F4;padding:32px 0">
45	    <tr><td align="center">
46	      <table width="560" cellpadding="0" cellspacing="0" style="max-width:560px;width:100%">
47	        <tr><td style="background:#040D6D;border-radius:16px 16px 0 0;padding:32px 36px 26px">
48	          <p style="margin:0 0 4px;font-size:11px;letter-spacing:.15em;text-transform:uppercase;color:#58ABFF">tax invoice</p>
49	          <p style="margin:0 0 18px;font-size:15px;font-weight:600;color:#fff">${merchantName}</p>
50	          <p style="margin:0 0 6px;font-size:11px;letter-spacing:.2em;text-transform:uppercase;color:rgba(88,171,255,0.6)">paid in full</p>
51	          <p style="margin:0;font-size:48px;font-weight:700;letter-spacing:-2px;color:#58ABFF;line-height:1">${total}</p>
52	        </td></tr>
53	        <tr><td style="background:#fff;padding:26px 36px 30px">
54	          <table width="100%" cellpadding="0" cellspacing="0">
55	            <tr><td style="padding-bottom:14px">
56	              <p style="margin:0 0 2px;font-size:10px;letter-spacing:.15em;text-transform:uppercase;color:#8C8C8C">billed to</p>
57	              <p style="margin:0;font-size:14px;font-weight:600;color:#040D6D">${tenantName}</p>
58	              <p style="margin:2px 0 0;font-size:13px;color:#8C8C8C">${propertyAddress}</p>
59	            </td></tr>
60	            <tr><td style="padding:14px 0;border-top:1px solid #F0F0F0">
